21	/**
22	 * Get the full external API URL (e.g. "https://api.esdeveniments.cat/api").
23	 *
24	 * Uses indirect env access so Turbopack does NOT inline the value at build
25	 * time. This means the runtime value (set by Coolify / Docker ENV) is always
26	 * read, and when the var is genuinely absent the JSON default kicks in.
27	 */
28	const _envKey = "NEXT_PUBLIC_API_URL";
29	export function getApiUrl(): string {
30	  return process.env[_envKey] || DEFAULT_API_URL;
31	}
