77	/**
78	 * Optional Vercel Deployment Protection bypass header.
79	 *
80	 * When Deployment Protection is enabled, server-side fetches to the same deployment
81	 * (e.g. calling internal API routes via an absolute URL) will not automatically
82	 * include the browser's Vercel auth cookies.
83	 *
84	 * If a Protection Bypass secret is configured in Vercel, attaching this header
85	 * allows SSR/ISR requests to reach internal routes.
86	 */
87	export function getVercelProtectionBypassHeaders(): Record<string, string> {
88	  const secret = process.env.VERCEL_AUTOMATION_BYPASS_SECRET;
89	  if (!secret) return {};
90	  return { "x-vercel-protection-bypass": secret };
91	}
