93	/**
94	 * Build an absolute URL to the app's own API routes (App Router `/api/*`).
95	 * This is necessary when running without a request context (e.g., during build
96	 * or static generation), where relative URLs are invalid in Node's fetch.
97	 *
98	 * Preview/staging deployments should provide INTERNAL_SITE_URL or VERCEL_URL.
99	 * Request Host is only trusted for exact localhost development hosts.
100	 */
101	export async function getInternalApiUrl(
102	  path: string,
103	  options: InternalOriginOptions = {},
104	): Promise<string> {
105	  const normalized = path.startsWith("/") ? path : `/${path}`;
106	
107	  // Priority 1: Try to get host from request headers (works in server components)
108	  // This ensures Vercel preview URLs are correctly resolved.
109	  // Skipped when preferConfiguredOrigin is set: reading headers() makes the
110	  // caller dynamic, which under cacheComponents must be avoided in
111	  // generateMetadata (otherwise the metadata boundary lands in the resume tree
112	  // and mismatches the static shell). Metadata uses the configured origin below.
113	  if (headersFn && !options.preferConfiguredOrigin) {
114	    try {
115	      const headersList = await headersFn();
116	      const host = headersList.get("host");
117	
118	      if (host) {
119	        if (isDevelopmentHost(host)) {
120	          const origin = `http://${host}`;
121	          try {
122	            return new URL(normalized, origin).toString();
123	          } catch {
124	            // Fall through to next priority
125	          }
126	        }
127	      }
128	    } catch {
129	      // headers() may throw in some contexts (e.g., during build)
130	      // Fall through to next priority
131	    }
132	  }
133	
134	  // Priority 2: Explicit internal hostname (bypasses public CDN/Cloudflare)
135	  const internalSiteUrl = process.env.INTERNAL_SITE_URL;
136	  if (internalSiteUrl) {
137	    try {
138	      return new URL(normalized, internalSiteUrl).toString();
139	    } catch (error) {
140	      console.warn(
141	        `[getInternalApiUrl] Invalid INTERNAL_SITE_URL "${internalSiteUrl}":`,
142	        error,
143	      );
144	    }
145	  }
146	
147	  // Priority 3: Vercel deployments (check before NEXT_PUBLIC_SITE_URL to ensure preview URLs work)
148	  // VERCEL_URL is provided at runtime and points to the exact deployment host.
149	  // It does not include the protocol.
150	  const vercelUrl =
151	    process.env.VERCEL_URL || process.env.NEXT_PUBLIC_VERCEL_URL || "";
152	  if (vercelUrl) {
153	    const origin = vercelUrl.startsWith("http")
154	      ? vercelUrl
155	      : `https://${vercelUrl}`;
156	    try {
157	      return new URL(normalized, origin).toString();
158	    } catch (error) {
159	      console.warn(
160	        `[getInternalApiUrl] Invalid VERCEL_URL "${vercelUrl}":`,
161	        error,
162	      );
163	    }
164	  }
165	
166	  // Priority 4: Explicit canonical hostname (used when internal/Vercel URLs aren't available)
167	  if (process.env.NEXT_PUBLIC_SITE_URL) {
168	    try {
169	      return new URL(normalized, process.env.NEXT_PUBLIC_SITE_URL).toString();
170	    } catch (error) {
171	      console.warn(
172	        `[getInternalApiUrl] Invalid NEXT_PUBLIC_SITE_URL "${process.env.NEXT_PUBLIC_SITE_URL}":`,
173	        error,
174	      );
175	    }
176	  }
177	
178	  // Priority 5: Fallback to runtime-computed siteUrl (ensures correct env vars are used)
179	  // Call getSiteUrl() at runtime instead of using module-level constant
180	  const siteUrl = getSiteUrl();
181	  return new URL(normalized, siteUrl).toString();
182	}
