184	/**
185	 * Build URLSearchParams from FetchEventsParams.
186	 * Centralizes query string construction to eliminate duplication between
187	 * internal and external API calls.
188	 */
189	export function buildEventsQuery(params: FetchEventsParams): URLSearchParams {
190	  const query: Partial<FetchEventsParams> = {};
191	  query.page = typeof params.page === "number" ? params.page : 0;
192	  query.size = typeof params.size === "number" ? params.size : 10;
193	
194	  if (params.place) query.place = params.place;
195	  if (params.category) query.category = params.category;
196	  if (params.lat !== undefined) query.lat = params.lat;
197	  if (params.lon !== undefined) query.lon = params.lon;
198	  if (params.radius !== undefined) query.radius = params.radius;
199	  if (params.term) query.term = params.term;
200	  if (params.byDate) query.byDate = params.byDate;
201	  if (params.from) query.from = params.from;
202	  if (params.to) query.to = params.to;
203	  if (params.type) query.type = params.type;
204	
205	  return new URLSearchParams(
206	    Object.fromEntries(
207	      Object.entries(query)
208	        .filter(([, v]) => v !== undefined)
209	        .map(([k, v]) => [k, String(v)]),
210	    ),
211	  );
212	}
