228	    query.size = typeof params.size === "number" ? params.size : 100;
229	  } else {
230	    if (typeof params.page === "number") query.page = params.page;
231	    if (typeof params.size === "number") query.size = params.size;
232	  }
233	  if (params.place) query.place = params.place;
234	
235	  return new URLSearchParams(
236	    Object.fromEntries(
237	      Object.entries(query)
238	        .filter(([, v]) => v !== undefined)
239	        .map(([k, v]) => [k, String(v)]),
240	    ),
241	  );
