244	/**
245	 * Apply distance/radius filter to FetchEventsParams if coordinates are provided.
246	 * Centralizes the distance filter logic used across all event list pages.
247	 * @param params - The fetch params object to mutate
248	 * @param input - Location data (lat, lon, distance) - accepts numbers or strings for flexibility
249	 * @returns The same params object (for chaining if needed)
250	 */
251	export function applyDistanceToParams(
252	  params: FetchEventsParams,
253	  input: {
254	    lat?: number | string;
255	    lon?: number | string;
256	    distance?: number | string;
257	  },
258	): FetchEventsParams {
259	  // Parse lat/lon from string or number
260	  const lat =
261	    input.lat !== undefined
262	      ? typeof input.lat === "string"
263	        ? parseFloat(input.lat)
264	        : input.lat
265	      : undefined;
266	  const lon =
267	    input.lon !== undefined
268	      ? typeof input.lon === "string"
269	        ? parseFloat(input.lon)
270	        : input.lon
271	      : undefined;
272	
273	  // Only apply if both coordinates are valid numbers
274	  if (lat !== undefined && lon !== undefined && !isNaN(lat) && !isNaN(lon)) {
275	    const maybeRadius = distanceToRadius(input.distance);
276	    if (maybeRadius !== undefined) {
277	      params.radius = maybeRadius;
278	    }
279	    params.lat = lat;
280	    params.lon = lon;
281	  }
282	
283	  return params;
284	}
