76	export async function generatePagesData({
77	  currentYear,
78	  place = "",
79	  byDate = "",
80	  placeTypeLabel,
81	  category,
82	  categoryName,
83	  search,
84	  locale,
85	}: GeneratePagesDataProps & {
86	  placeTypeLabel: PlaceTypeAndLabel;
87	  locale?: AppLocale;
88	}): Promise<PageData> {
89	  // No dynamic API (headers/cookies/searchParams) is read here — the only
90	  // request-time value is `now`, used solely as a fallback for the current
91	  // month/year label on pages with no explicit date/year/month segment (see
92	  // effectiveYear/monthIndex below). Caching this "hours" trades exact
93	  // per-request freshness for prerenderability: on a calendar-month rollover,
94	  // the label can lag by up to ~1h (the "hours" profile's revalidate window)
95	  // before self-correcting, same eventual-consistency tradeoff already made
96	  // for places/regions/categories elsewhere in this fix. connection() here
97	  // used to force this dynamic for every caller, including metadata, which
98	  // broke the PPR static shell. See
99	  // docs/incidents/2026-06-13-cachecomponents-metadata-resume-mismatch.md.
100	  "use cache";
101	  cacheTag(placesTag, placeTag(place || "catalunya"));
102	  cacheLife("hours");
103	
104	  const resolvedLocale = locale || DEFAULT_LOCALE;
105	
106	  // Parallelize translation fetches to eliminate waterfall (2 calls → 1 round trip)
107	  const [t, tConstants] = await Promise.all([
108	    getTranslations({
109	      locale: resolvedLocale,
110	      namespace: "Partials.GeneratePagesData",
111	    }),
112	    getTranslations({
113	      locale: resolvedLocale,
114	      namespace: "Components.Constants",
115	    }),
116	  ]);
117	
118	  const now = new Date();
119	
120	  // Used only for parsing numeric month/year parts deterministically.
121	  // We force Latin digits to keep Number(...) stable across locales.
122	  const intlNumberLocale =
123	    resolvedLocale === "ca"
124	      ? "ca-ES-u-nu-latn"
125	      : resolvedLocale === "es"
126	      ? "es-ES-u-nu-latn"
127	      : "en-GB-u-nu-latn";
