129	    currentYear ??
130	    (() => {
131	      try {
132	        const parts = new Intl.DateTimeFormat(intlNumberLocale, {
133	          timeZone: "Europe/Madrid",
134	          year: "numeric",
135	        }).formatToParts(now);
136	
137	        const yearPart = parts.find((p) => p.type === "year")?.value;
138	        const yearNumber = yearPart ? Number(yearPart) : NaN;
139	
140	        if (
141	          !Number.isFinite(yearNumber) ||
142	          yearNumber < 2000 ||
143	          yearNumber > 3000
144	        ) {
145	          return now.getFullYear();
146	        }
147	
148	        return yearNumber;
149	      } catch {
150	        return now.getFullYear();
151	      }
152	    })();
153	
154	  const months = (tConstants.raw("months") as string[]) || [];
155	  const monthIndex = (() => {
156	    try {
157	      const parts = new Intl.DateTimeFormat(intlNumberLocale, {
158	        timeZone: "Europe/Madrid",
159	        month: "numeric",
160	      }).formatToParts(now);
161	      const monthPart = parts.find((p) => p.type === "month")?.value;
162	      const monthNumber = monthPart ? Number(monthPart) : NaN;
163	      if (
164	        !Number.isFinite(monthNumber) ||
165	        monthNumber < 1 ||
166	        monthNumber > 12
167	      ) {
168	        return now.getMonth();
169	      }
170	      return monthNumber - 1;
171	    } catch {
172	      return now.getMonth();
173	    }
174	  })();
175	
176	  const month = months[monthIndex] || "";
177	
178	  const categoryTemplates = (t.raw("categories") || {}) as Record<
179	    string,
180	    {
181	      titleSuffix: string;
182	      description: string;
183	      context: string;
184	      noEvents: string;
185	    }
186	  >;
187	  const getCategorySEO = (categorySlug?: string) => {
188	    if (!categorySlug) return null;
189	    return categoryTemplates[categorySlug] || null;
190	  };
