1	/**
2	 * Cache tag helpers for Next.js 16 tag-based caching
3	 * Provides type-safe tag builders and constants
4	 */
5	import type { CacheTag } from "types/cache";
6	
7	/** Next.js rejects cache tags longer than 256 characters. */
8	const MAX_TAG_LENGTH = 256;
9	
10	/** Stable, non-cryptographic short hash (djb2) used to shorten oversized tags. */
11	function shortTagHash(input: string): string {
12	  let hash = 5381;
13	  for (let i = 0; i < input.length; i += 1) {
14	    hash = ((hash << 5) + hash + input.charCodeAt(i)) >>> 0;
15	  }
16	  return hash.toString(16).padStart(8, "0");
17	}
18	
19	/**
20	 * Build a `<prefix>:<value>` tag that always fits Next.js's 256-char limit.
21	 * Oversized values (e.g. a malformed event id that carries a whole URL +
22	 * description from a bad RSS parse) are truncated with a stable hash suffix, so
23	 * the tag stays unique and identical across the fetch (set) and the
24	 * updateTag/revalidateTag (invalidate) paths. Short values pass through verbatim.
25	 */
26	function boundedTag<Prefix extends string>(
27	  prefix: Prefix,
28	  value: string,
29	): `${Prefix}:${string}` {
30	  const tag = `${prefix}:${value}`;
31	  if (tag.length <= MAX_TAG_LENGTH) return tag as `${Prefix}:${string}`;
32	  const hash = shortTagHash(value);
33	  // Reserve room for the ":" separator and the "-<hash>" suffix.
34	  const keep = MAX_TAG_LENGTH - prefix.length - 2 - hash.length;
35	  return `${prefix}:${value.slice(0, Math.max(0, keep))}-${hash}` as `${Prefix}:${string}`;
36	}
37	
38	// Event tags
39	export const eventsTag = "events" as const satisfies CacheTag;
40	export const eventsCategorizedTag = "events:categorized" as const satisfies CacheTag;
41	export const eventTag = (slug: string): `event:${string}` =>
42	  boundedTag("event", slug);
43	
44	// Place tags
45	export const placesTag = "places" as const satisfies CacheTag;
46	export const placeTag = (slug: string): `place:${string}` =>
47	  boundedTag("place", slug);
48	
49	// City tags
50	export const citiesTag = "cities" as const satisfies CacheTag;
51	export const cityTag = (id: string | number): `city:${string}` =>
